/**
 * Dummy Runner - 在瀏覽器中執行模型推理測試
 * 使用隨機輸入測試模型，獲取實際輸出形狀和性能指標
 */

export class DummyRunner {
    constructor() {
        this.ort = null;
        this.isInitialized = false;
    }

    /**
     * 初始化 ONNX Runtime Web
     */
    async initialize() {
        if (this.isInitialized) {
            return;
        }

        try {
            // 動態載入 ONNX Runtime Web
            if (typeof window === 'undefined') {
                // Node.js 環境
                this.ort = await import('onnxruntime-web');
            } else {
                // 瀏覽器環境
                const script = document.createElement('script');
                script.src = 'https://cdn.jsdelivr.net/npm/onnxruntime-web@1.18.0/dist/ort.min.js';
                document.head.appendChild(script);

                await new Promise((resolve, reject) => {
                    script.onload = resolve;
                    script.onerror = reject;
                });

                this.ort = window.ort;
            }

            this.isInitialized = true;
            // eslint-disable-next-line no-console
            console.log('ONNX Runtime Web 初始化成功');
        } catch (error) {
            // eslint-disable-next-line no-console
            console.warn('ONNX Runtime Web 載入失敗:', error);
            throw new Error('無法載入 ONNX Runtime Web，dummy run 功能不可用');
        }
    }

    /**
     * 執行模型推理測試
     * @param {ArrayBuffer} modelBuffer - 模型二進位數據
     * @param {Object} summary - 模型摘要資訊
     * @returns {Object} 執行結果
     */
    async runModel(modelBuffer, summary) {
        if (!this.isInitialized) {
            await this.initialize();
        }

        if (summary.format.toLowerCase() !== 'onnx') {
            throw new Error(`目前僅支援 ONNX 模型，收到格式: ${summary.format}`);
        }

        try {
            // eslint-disable-next-line no-console
            console.log('開始載入 ONNX 模型...');
            const session = await this.ort.InferenceSession.create(modelBuffer);

            // eslint-disable-next-line no-console
            console.log('模型載入成功，準備輸入數據...');
            const inputs = this._prepareInputs(summary.inputs);

            // eslint-disable-next-line no-console
            console.log('開始推理...');
            const startTime = performance.now();
            const outputs = await session.run(inputs);
            const endTime = performance.now();

            const result = {
                success: true,
                inferenceTime: endTime - startTime,
                inputs: this._analyzeInputs(inputs),
                outputs: this._analyzeOutputs(outputs),
                memoryUsage: this._estimateMemoryUsage(inputs, outputs),
                metadata: {
                    provider: session.sessionOptions?.executionProviders || ['cpu'],
                    inputNames: session.inputNames,
                    outputNames: session.outputNames
                }
            };

            // eslint-disable-next-line no-console
            console.log('推理完成:', result);
            return result;

        } catch (error) {
            // eslint-disable-next-line no-console
            console.error('模型執行失敗:', error);
            return {
                success: false,
                error: error.message,
                details: error.stack
            };
        }
    }

    /**
     * 根據輸入規格準備隨機測試數據
     * @param {Array} inputSpecs - 輸入規格陣列
     * @returns {Object} 輸入張量字典
     */
    _prepareInputs(inputSpecs) {
        const inputs = {};

        for (const spec of inputSpecs) {
            const shape = this._resolveShape(spec.shape);
            const data = this._generateRandomData(shape, spec.dtype);
            const tensor = new this.ort.Tensor(this._mapDataType(spec.dtype), data, shape);
            inputs[spec.name] = tensor;
        }

        return inputs;
    }

    /**
     * 解析動態形狀，替換為具體數值
     * @param {Array} shape - 原始形狀陣列
     * @returns {Array} 解析後的形狀
     */
    _resolveShape(shape) {
        return shape.map((dim) => {
            if (dim === '?' || dim === -1 || dim === null || dim === undefined) {
                return 1; // 動態維度設為 1
            }
            if (typeof dim === 'string' && isNaN(parseInt(dim, 10))) {
                return 1; // 符號維度設為 1
            }
            return parseInt(dim, 10) || 1;
        });
    }

    /**
     * 生成隨機測試數據
     * @param {Array} shape - 張量形狀
     * @param {string} dtype - 數據類型
     * @returns {TypedArray} 隨機數據
     */
    _generateRandomData(shape, dtype) {
        const size = shape.reduce((a, b) => a * b, 1);

        switch (dtype.toLowerCase()) {
            case 'float32':
            case 'float':
                return new Float32Array(size).map(() => Math.random());

            case 'float64':
            case 'double':
                return new Float64Array(size).map(() => Math.random());

            case 'int32':
            case 'int':
                return new Int32Array(size).map(() => Math.floor(Math.random() * 256));

            case 'int64':
            case 'long':
                return new BigInt64Array(size).map(() => BigInt(Math.floor(Math.random() * 256)));

            case 'uint8':
            case 'byte':
                return new Uint8Array(size).map(() => Math.floor(Math.random() * 256));

            case 'int8':
                return new Int8Array(size).map(() => Math.floor(Math.random() * 256) - 128);

            case 'uint16':
                return new Uint16Array(size).map(() => Math.floor(Math.random() * 65536));

            case 'int16':
                return new Int16Array(size).map(() => Math.floor(Math.random() * 65536) - 32768);

            case 'bool':
            case 'boolean':
                return new Uint8Array(size).map(() => Math.random() > 0.5 ? 1 : 0);

            default:
                // eslint-disable-next-line no-console
                console.warn(`未知數據類型 ${dtype}，使用 Float32Array`);
                return new Float32Array(size).map(() => Math.random());
        }
    }

    /**
     * 映射數據類型到 ONNX Runtime 格式
     * @param {string} dtype - 原始數據類型
     * @returns {string} ONNX Runtime 數據類型
     */
    _mapDataType(dtype) {
        const typeMap = {
            'float32': 'float32',
            'float': 'float32',
            'float64': 'float64',
            'double': 'float64',
            'int32': 'int32',
            'int': 'int32',
            'int64': 'int64',
            'long': 'int64',
            'uint8': 'uint8',
            'byte': 'uint8',
            'int8': 'int8',
            'uint16': 'uint16',
            'int16': 'int16',
            'bool': 'bool',
            'boolean': 'bool'
        };

        return typeMap[dtype.toLowerCase()] || 'float32';
    }

    /**
     * 分析輸入數據
     * @param {Object} inputs - 輸入張量字典
     * @returns {Array} 輸入分析結果
     */
    _analyzeInputs(inputs) {
        const analysis = [];

        for (const [name, tensor] of Object.entries(inputs)) {
            analysis.push({
                name,
                shape: Array.from(tensor.dims),
                dtype: tensor.type,
                size: tensor.size,
                min: this._getTensorMin(tensor.data),
                max: this._getTensorMax(tensor.data),
                mean: this._getTensorMean(tensor.data)
            });
        }

        return analysis;
    }

    /**
     * 分析輸出數據
     * @param {Object} outputs - 輸出張量字典
     * @returns {Array} 輸出分析結果
     */
    _analyzeOutputs(outputs) {
        const analysis = [];

        for (const [name, tensor] of Object.entries(outputs)) {
            analysis.push({
                name,
                shape: Array.from(tensor.dims),
                dtype: tensor.type,
                size: tensor.size,
                min: this._getTensorMin(tensor.data),
                max: this._getTensorMax(tensor.data),
                mean: this._getTensorMean(tensor.data),
                sample: this._getSampleValues(tensor.data, 10)
            });
        }

        return analysis;
    }

    /**
     * 估算記憶體使用量
     * @param {Object} inputs - 輸入張量
     * @param {Object} outputs - 輸出張量
     * @returns {Object} 記憶體使用統計
     */
    _estimateMemoryUsage(inputs, outputs) {
        let inputMemory = 0;
        let outputMemory = 0;

        for (const tensor of Object.values(inputs)) {
            inputMemory += this._getTensorMemorySize(tensor);
        }

        for (const tensor of Object.values(outputs)) {
            outputMemory += this._getTensorMemorySize(tensor);
        }

        return {
            input: inputMemory,
            output: outputMemory,
            total: inputMemory + outputMemory,
            unit: 'bytes'
        };
    }

    /**
     * 計算張量記憶體大小
     * @param {Tensor} tensor - ONNX 張量
     * @returns {number} 記憶體大小（位元組）
     */
    _getTensorMemorySize(tensor) {
        const bytesPerElement = {
            'float32': 4,
            'float64': 8,
            'int32': 4,
            'int64': 8,
            'uint8': 1,
            'int8': 1,
            'uint16': 2,
            'int16': 2,
            'bool': 1
        };

        return tensor.size * (bytesPerElement[tensor.type] || 4);
    }

    /**
     * 獲取張量最小值
     */
    _getTensorMin(data) {
        return Math.min(...Array.from(data));
    }

    /**
     * 獲取張量最大值
     */
    _getTensorMax(data) {
        return Math.max(...Array.from(data));
    }

    /**
     * 獲取張量平均值
     */
    _getTensorMean(data) {
        const sum = Array.from(data).reduce((a, b) => a + b, 0);
        return sum / data.length;
    }

    /**
     * 獲取張量樣本值
     * @param {TypedArray} data - 張量數據
     * @param {number} count - 樣本數量
     * @returns {Array} 樣本值陣列
     */
    _getSampleValues(data, count = 10) {
        const samples = [];
        const step = Math.max(1, Math.floor(data.length / count));

        for (let i = 0; i < data.length && samples.length < count; i += step) {
            samples.push(data[i]);
        }

        return samples;
    }

    /**
     * 檢查是否支援 ONNX Runtime Web
     * @returns {boolean} 是否支援
     */
    static isSupported() {
        return typeof WebAssembly !== 'undefined' &&
               typeof Worker !== 'undefined' &&
               typeof fetch !== 'undefined';
    }

    /**
     * 獲取支援的執行提供者
     * @returns {Array} 執行提供者列表
     */
    static getSupportedProviders() {
        const providers = ['cpu'];

        // 檢查 WebGL 支援
        if (typeof WebGLRenderingContext !== 'undefined') {
            providers.push('webgl');
        }

        // 檢查 WebGPU 支援
        if (typeof navigator !== 'undefined' && navigator.gpu) {
            providers.push('webgpu');
        }

        return providers;
    }
}

/**
 * Exporter - 匯出模型卡片和程式碼範例
 * 支援匯出 Markdown 格式的模型卡片和可執行的程式碼範例
 */

export class Exporter {
    constructor() {
        // 延遲初始化模板，避免建構函數中的方法調用問題
        this.defaultTemplates = null;
    }

    /**
     * 獲取預設模板（延遲初始化）
     */
    _getDefaultTemplates() {
        if (!this.defaultTemplates) {
            this.defaultTemplates = {
                readme: this._getReadmeTemplate(),
                quickstart: this._getQuickstartTemplate(),
                requirements: this._getRequirementsTemplate()
            };
        }
        return this.defaultTemplates;
    }

    /**
     * 匯出完整的模型包
     * @param {Object} summary - 模型摘要
     * @param {Object} explanation - 模型解釋
     * @param {Object} options - 匯出選項
     * @returns {Promise<Blob>} ZIP 檔案
     */
    async exportModelPackage(summary, explanation, options = {}) {
        const files = await this._generateFiles(summary, explanation, options);
        return this._createZipFile(files);
    }

    /**
     * 匯出 Model Card (README.md)
     * @param {Object} summary - 模型摘要
     * @param {Object} explanation - 模型解釋
     * @param {Object} options - 匯出選項
     * @returns {string} Markdown 內容
     */
    exportModelCard(summary, explanation, options = {}) {
        const templates = this._getDefaultTemplates();
        const template = templates.readme;

        return template
            .replace('{modelName}', summary.modelName)
            .replace('{format}', summary.format)
            .replace('{taskGuess}', this._translateTask(summary.taskGuess))
            .replace('{purpose}', explanation.purpose || '待補充')
            .replace('{inputRequirements}', this._formatInputRequirements(explanation.inputRequirements))
            .replace('{outputMeaning}', this._formatOutputMeaning(explanation.outputMeaning))
            .replace('{applications}', this._formatApplications(explanation.applications))
            .replace('{limitations}', this._formatLimitations(explanation.limitations))
            .replace('{performance}', this._formatPerformance(explanation.performance))
            .replace('{metadata}', this._formatMetadata(summary.metadata))
            .replace('{date}', new Date().toISOString().split('T')[0]);
    }

    /**
     * 匯出 Quickstart 程式碼
     * @param {Object} summary - 模型摘要
     * @param {Object} explanation - 模型解釋
     * @param {string} language - 程式語言
     * @returns {string} 程式碼內容
     */
    exportQuickstartCode(summary, explanation, language = 'python') {
        const codeTemplate = explanation.quickstartCode?.[language];
        if (codeTemplate) {
            return codeTemplate;
        }

        // 如果沒有 LLM 生成的程式碼，使用預設模板
        return this._generateDefaultCode(summary, language);
    }

    /**
     * 匯出 requirements.txt
     * @param {Object} summary - 模型摘要
     * @returns {string} 依賴清單
     */
    exportRequirements(summary) {
        const format = summary.format.toLowerCase();
        const baseRequirements = this._getBaseRequirements(format);

        let requirements = baseRequirements.join('\n');

        // 添加註解
        requirements += '\n\n# 模型推理依賴\n';
        requirements += `# 格式: ${summary.format}\n`;
        requirements += `# 任務: ${summary.taskGuess}\n`;

        if (summary.quantization.isQuantized) {
            requirements += '# 量化模型，可能需要特殊版本的推理引擎\n';
        }

        return requirements;
    }

    /**
     * 生成所有檔案
     */
    async _generateFiles(summary, explanation, options) {
        const files = [];

        // README.md
        files.push({
            name: 'README.md',
            content: this.exportModelCard(summary, explanation, options)
        });

        // quickstart.py
        files.push({
            name: 'quickstart.py',
            content: this.exportQuickstartCode(summary, explanation, 'python')
        });

        // requirements.txt
        files.push({
            name: 'requirements.txt',
            content: this.exportRequirements(summary)
        });

        // 如果有 JavaScript 程式碼，也匯出
        if (explanation.quickstartCode?.javascript) {
            files.push({
                name: 'quickstart.js',
                content: explanation.quickstartCode.javascript
            });

            files.push({
                name: 'package.json',
                content: this._generatePackageJson(summary)
            });
        }

        // 模型摘要 JSON
        files.push({
            name: 'model_summary.json',
            content: JSON.stringify(summary, null, 2)
        });

        return files;
    }

    /**
     * 建立 ZIP 檔案
     */
    async _createZipFile(files) {
        // 使用瀏覽器原生 API 或載入 JSZip
        if (typeof window !== 'undefined' && window.JSZip) {
            return this._createZipWithJSZip(files);
        }

        // 簡化版：返回檔案陣列（可以在 UI 中處理）
        return files;
    }

    /**
     * 使用 JSZip 建立 ZIP
     */
    async _createZipWithJSZip(files) {
        const zip = new window.JSZip();

        for (const file of files) {
            zip.file(file.name, file.content);
        }

        return await zip.generateAsync({ type: 'blob' });
    }

    /**
     * 格式化輸入需求
     */
    _formatInputRequirements(requirements) {
        if (!requirements || requirements.length === 0) {
            return '待補充';
        }

        return requirements.map((req) => {
            let formatted = `### ${req.name}\n`;
            formatted += `- **形狀**: \`${JSON.stringify(req.shape)}\`\n`;
            formatted += `- **類型**: \`${req.dtype}\`\n`;
            formatted += `- **領域**: ${req.domain}\n`;
            formatted += `- **描述**: ${req.description}\n`;

            if (req.preprocessing && req.preprocessing.length > 0) {
                formatted += `- **前處理**:\n`;
                for (const step of req.preprocessing) {
                    formatted += `  - ${step}\n`;
                }
            }

            return formatted;
        }).join('\n');
    }

    /**
     * 格式化輸出含義
     */
    _formatOutputMeaning(meanings) {
        if (!meanings || meanings.length === 0) {
            return '待補充';
        }

        return meanings.map((meaning) => {
            let formatted = `### ${meaning.name}\n`;
            formatted += `- **形狀**: \`${JSON.stringify(meaning.shape)}\`\n`;
            formatted += `- **類型**: \`${meaning.dtype}\`\n`;
            formatted += `- **語義**: ${meaning.semantics}\n`;
            formatted += `- **描述**: ${meaning.description}\n`;

            if (meaning.postprocessing && meaning.postprocessing.length > 0) {
                formatted += `- **後處理**:\n`;
                for (const step of meaning.postprocessing) {
                    formatted += `  - ${step}\n`;
                }
            }

            return formatted;
        }).join('\n');
    }

    /**
     * 格式化應用場景
     */
    _formatApplications(applications) {
        if (!applications || applications.length === 0) {
            return '待補充';
        }

        return applications.map((app) => `- ${app}`).join('\n');
    }

    /**
     * 格式化限制說明
     */
    _formatLimitations(limitations) {
        if (!limitations || limitations.length === 0) {
            return '待補充';
        }

        return limitations.map((limitation) => `- ${limitation}`).join('\n');
    }

    /**
     * 格式化性能說明
     */
    _formatPerformance(performance) {
        if (!performance || performance.length === 0) {
            return '待補充';
        }

        return performance.map((note) => `- ${note}`).join('\n');
    }

    /**
     * 格式化元數據
     */
    _formatMetadata(metadata) {
        if (!metadata || Object.keys(metadata).length === 0) {
            return '無額外元數據';
        }

        return Object.entries(metadata)
            .filter(([, value]) => value)
            .map(([key, value]) => `- **${key}**: ${value}`)
            .join('\n');
    }

    /**
     * 翻譯任務類型
     */
    _translateTask(task) {
        const translations = {
            'classification': '圖像分類',
            'detection': '物件偵測',
            'pose': '姿態估計',
            'segmentation': '影像分割',
            'unknown': '未知任務'
        };
        return translations[task] || task;
    }

    /**
     * 獲取基礎依賴
     */
    _getBaseRequirements(format) {
        const requirements = {
            'onnx': ['onnxruntime>=1.15.0', 'numpy>=1.21.0'],
            'tflite': ['tensorflow>=2.12.0', 'numpy>=1.21.0'],
            'coreml': ['coremltools>=7.0', 'numpy>=1.21.0'],
            'tensorrt': ['tensorrt>=8.0.0', 'numpy>=1.21.0', 'pycuda>=2022.1'],
            'openvino': ['openvino>=2023.0.0', 'numpy>=1.21.0']
        };

        return requirements[format] || ['numpy>=1.21.0'];
    }

    /**
     * 生成預設程式碼
     */
    _generateDefaultCode(summary, language) {
        if (language === 'python') {
            return this._generateDefaultPythonCode(summary);
        }
        if (language === 'javascript') {
            return this._generateDefaultJavaScriptCode(summary);
        }
        return '# 暫不支援此程式語言';
    }

    /**
     * 生成預設 Python 程式碼
     */
    _generateDefaultPythonCode(summary) {
        const format = summary.format.toLowerCase();
        const input = summary.inputs[0];
        const inputShape = input ? JSON.stringify(input.shape) : '[1, 3, 224, 224]';
        const inputName = input ? input.name : 'input';

        if (format === 'onnx') {
            return `#!/usr/bin/env python3
"""
${summary.modelName} - ONNX 推理範例
自動生成於 ${new Date().toISOString().split('T')[0]}
"""

import onnxruntime as ort
import numpy as np

def load_model(model_path):
    """載入 ONNX 模型"""
    session = ort.InferenceSession(model_path)
    return session

def preprocess_input(data):
    """前處理輸入數據"""
    # TODO: 根據實際需求調整前處理步驟
    return data.astype(np.float32)

def run_inference(session, input_data):
    """執行推理"""
    input_name = session.get_inputs()[0].name
    outputs = session.run(None, {input_name: input_data})
    return outputs

def main():
    # 載入模型
    model_path = "model.onnx"
    session = load_model(model_path)

    # 準備測試數據
    input_shape = ${inputShape}
    test_input = np.random.random(input_shape).astype(np.float32)

    # 前處理
    processed_input = preprocess_input(test_input)

    # 執行推理
    outputs = run_inference(session, processed_input)

    # 顯示結果
    for i, output in enumerate(outputs):
        print(f"Output {i}: shape={output.shape}, dtype={output.dtype}")
        print(f"Sample values: {output.flat[:5]}")

if __name__ == "__main__":
    main()`;
        }

        return `# ${summary.modelName} 推理範例
# 格式: ${summary.format}
# 請根據具體格式選擇適當的推理框架`;
    }

    /**
     * README 模板
     */
    _getReadmeTemplate() {
        return `# {modelName}

> 自動生成的模型卡片 - {date}

## 模型資訊

- **格式**: {format}
- **任務**: {taskGuess}

## 模型用途

{purpose}

## 輸入需求

{inputRequirements}

## 輸出含義

{outputMeaning}

## 應用場景

{applications}

## 快速開始

\`\`\`bash
# 安裝依賴
pip install -r requirements.txt

# 執行範例
python quickstart.py
\`\`\`

## 性能建議

{performance}

## 限制說明

{limitations}

## 技術細節

{metadata}

## 授權聲明

請遵守原模型的授權條款。

---

*此文檔由 Netron Explain 工具自動生成*`;
    }

    /**
     * Quickstart 程式碼模板
     */
    _getQuickstartTemplate() {
        return `#!/usr/bin/env python3
"""
{modelName} - 快速開始範例
自動生成於 {date}
"""

import numpy as np
{imports}

