/**
 * Validator - 驗證 LLM 輸出與實際模型資訊的一致性
 * 確保生成的解釋和程式碼符合模型實際規格
 */

export class Validator {
    constructor() {
        this.validationRules = {
            shape: this._validateShapes.bind(this),
            dtype: this._validateDataTypes.bind(this),
            format: this._validateFormat.bind(this),
            code: this._validateCode.bind(this),
            consistency: this._validateConsistency.bind(this)
        };
    }

    /**
     * 驗證 LLM 輸出是否與模型摘要一致
     * @param {string} llmOutput - LLM 生成的解釋
     * @param {Object} originalSummary - 原始模型摘要
     * @returns {Object} 驗證結果
     */
    validate(llmOutput, originalSummary) {
        const validationResult = {
            isValid: true,
            errors: [],
            warnings: [],
            suggestions: [],
            confidence: 1.0,
            provenanceIssues: [],  // 新增：來源問題
            consistencyChecks: {}  // 新增：一致性檢查結果
        };

        // 執行各種驗證規則
        for (const [ruleName, ruleFunc] of Object.entries(this.validationRules)) {
            try {
                const result = ruleFunc(llmOutput, originalSummary);

                if (!result.isValid) {
                    validationResult.isValid = false;
                    validationResult.errors.push(...result.errors);
                }

                validationResult.warnings.push(...result.warnings);
                validationResult.suggestions.push(...result.suggestions);
                validationResult.confidence = Math.min(validationResult.confidence, result.confidence);

                // 儲存一致性檢查結果
                validationResult.consistencyChecks[ruleName] = result;

            } catch (error) {
                validationResult.warnings.push(`驗證規則 ${ruleName} 執行失敗: ${error.message}`);
            }
        }

        // 新增：檢查 provenance 和 confidence 合理性
        this._validateProvenance(originalSummary, validationResult);

        return validationResult;
    }

    /**
     * 驗證輸入輸出形狀是否一致
     */
    _validateShapes(llmOutput, summary) {
        const result = {
            isValid: true,
            errors: [],
            warnings: [],
            suggestions: [],
            confidence: 1.0
        };

        // 提取 LLM 輸出中的形狀資訊
        const shapePatterns = [
            /\[(\d+(?:,\s*\d+)*)\]/g,           // [1, 3, 224, 224]
            /(\d+)x(\d+)/g,                     // 224x224
            /shape.*?(\d+(?:,\s*\d+)*)/gi,      // shape (1, 3, 224, 224)
            /尺寸.*?(\d+(?:,\s*\d+)*)/g         // 尺寸 224x224
        ];

        const extractedShapes = [];
        for (const pattern of shapePatterns) {
            let match;
            while ((match = pattern.exec(llmOutput)) !== null) {
                extractedShapes.push(match[1] || match[0]);
            }
        }

        // 檢查是否與實際輸入輸出形狀一致
        const actualInputShapes = summary.inputs.map((input) => input.shape.join(','));
        const actualOutputShapes = summary.outputs.map((output) => output.shape.join(','));
        const allActualShapes = [...actualInputShapes, ...actualOutputShapes];

        for (const extractedShape of extractedShapes) {
            const normalizedShape = extractedShape.replace(/\s/g, '');
            const isMatched = allActualShapes.some((actualShape) =>
                actualShape.replace(/\s/g, '') === normalizedShape
            );

            if (!isMatched) {
                result.warnings.push(`檢測到不一致的形狀: ${extractedShape}`);
                result.confidence *= 0.9;
            }
        }

        return result;
    }

    /**
     * 驗證數據類型是否正確
     */
    _validateDataTypes(llmOutput, summary) {
        const result = {
            isValid: true,
            errors: [],
            warnings: [],
            suggestions: [],
            confidence: 1.0
        };

        // 提取 LLM 輸出中的數據類型
        const dtypePatterns = [
            /float32|float64|int32|int64|uint8|int8|bool/gi,
            /浮點數|整數|布林/g
        ];

        const extractedDtypes = [];
        for (const pattern of dtypePatterns) {
            const matches = llmOutput.match(pattern) || [];
            extractedDtypes.push(...matches);
        }

        // 檢查是否與實際數據類型一致
        const actualDtypes = [
            ...summary.inputs.map((input) => input.dtype),
            ...summary.outputs.map((output) => output.dtype)
        ];

        // 簡單檢查是否包含正確的數據類型
        if (extractedDtypes.length > 0 && actualDtypes.length > 0) {
            const hasValidDtype = extractedDtypes.some((extracted) =>
                actualDtypes.some((actual) =>
                    actual.toLowerCase().includes(extracted.toLowerCase())
                )
            );

            if (!hasValidDtype) {
                result.warnings.push('檢測到可能不正確的數據類型');
                result.confidence *= 0.9;
            }
        }

        return result;
    }

    /**
     * 驗證模型格式是否正確
     */
    _validateFormat(llmOutput, summary) {
        const result = {
            isValid: true,
            errors: [],
            warnings: [],
            suggestions: [],
            confidence: 1.0
        };

        const actualFormat = summary.format.toLowerCase();
        const formatMentioned = llmOutput.toLowerCase().includes(actualFormat);

        if (!formatMentioned) {
            result.warnings.push(`LLM 輸出中未提及正確的模型格式: ${summary.format}`);
            result.confidence *= 0.95;
        }

        // 檢查是否提及了錯誤的格式
        const allFormats = ['onnx', 'tflite', 'coreml', 'tensorrt', 'openvino', 'pytorch', 'tensorflow'];
        const mentionedFormats = allFormats.filter((format) =>
            format !== actualFormat && llmOutput.toLowerCase().includes(format)
        );

        if (mentionedFormats.length > 0) {
            result.errors.push(`提及了錯誤的模型格式: ${mentionedFormats.join(', ')}`);
            result.isValid = false;
            result.confidence *= 0.7;
        }

        return result;
    }

    /**
     * 驗證程式碼範例是否正確
     */
    _validateCode(llmOutput, summary) {
        const result = {
            isValid: true,
            errors: [],
            warnings: [],
            suggestions: [],
            confidence: 1.0
        };

        // 提取程式碼區塊
        const codeBlocks = this._extractCodeBlocks(llmOutput);

        for (const codeBlock of codeBlocks) {
            const codeValidation = this._validateCodeBlock(codeBlock, summary);

            if (!codeValidation.isValid) {
                result.errors.push(...codeValidation.errors);
                result.isValid = false;
            }

            result.warnings.push(...codeValidation.warnings);
            result.confidence = Math.min(result.confidence, codeValidation.confidence);
        }

        return result;
    }

    /**
     * 驗證整體一致性
     */
    _validateConsistency(llmOutput, summary) {
        const result = {
            isValid: true,
            errors: [],
            warnings: [],
            suggestions: [],
            confidence: 1.0
        };

        // 檢查任務類型一致性
        const mentionedTasks = this._extractMentionedTasks(llmOutput);
        if (mentionedTasks.length > 0 && !mentionedTasks.includes(summary.taskGuess)) {
            if (summary.taskGuess !== 'unknown') {
                result.warnings.push(`推斷的任務類型不一致: LLM=${mentionedTasks}, 實際=${summary.taskGuess}`);
                result.confidence *= 0.85;
            }
        }

        // 檢查量化資訊一致性
        const mentionsQuantization = /量化|quantiz/i.test(llmOutput);
        if (mentionsQuantization !== summary.quantization.isQuantized) {
            result.warnings.push(`量化資訊不一致`);
            result.confidence *= 0.9;
        }

        return result;
    }

    /**
     * 提取程式碼區塊
     */
    _extractCodeBlocks(text) {
        const codeBlockRegex = /```[\s\S]*?```/g;
        const matches = text.match(codeBlockRegex) || [];
        return matches.map((match) => match.replace(/```/g, '').trim());
    }

    /**
     * 驗證單個程式碼區塊
     */
    _validateCodeBlock(code, summary) {
        const result = {
            isValid: true,
            errors: [],
            warnings: [],
            confidence: 1.0
        };

        // 檢查是否使用了正確的輸入名稱
        if (summary.inputs.length > 0) {
            const inputName = summary.inputs[0].name;
            if (inputName && !code.includes(inputName)) {
                result.warnings.push(`程式碼中未使用正確的輸入名稱: ${inputName}`);
                result.confidence *= 0.9;
            }
        }

        // 檢查是否使用了適當的推理框架
        const format = summary.format.toLowerCase();
        const expectedLibraries = {
            'onnx': ['onnxruntime', 'ort'],
            'tflite': ['tensorflow', 'tflite'],
            'coreml': ['coreml'],
            'tensorrt': ['tensorrt'],
            'openvino': ['openvino']
        };

        const expectedLibs = expectedLibraries[format] || [];
        const hasCorrectLibrary = expectedLibs.some((lib) => code.toLowerCase().includes(lib));

        if (!hasCorrectLibrary && expectedLibs.length > 0) {
            result.warnings.push(`程式碼未使用適當的推理框架，建議使用: ${expectedLibs.join(' 或 ')}`);
            result.confidence *= 0.8;
        }

        return result;
    }

    /**
     * 提取提及的任務類型
     */
    _extractMentionedTasks(text) {
        const taskKeywords = {
            'classification': ['分類', '識別', 'classification', 'classify'],
            'detection': ['偵測', '檢測', '物件', 'detection', 'detect', 'object'],
            'pose': ['姿態', '關鍵點', 'pose', 'keypoint', 'landmark'],
            'segmentation': ['分割', 'segmentation', 'segment']
        };

        const mentionedTasks = [];
        for (const [task, keywords] of Object.entries(taskKeywords)) {
            const isMentioned = keywords.some((keyword) =>
                text.toLowerCase().includes(keyword.toLowerCase())
            );
            if (isMentioned) {
                mentionedTasks.push(task);
            }
        }

        return mentionedTasks;
    }

    /**
     * 生成修正建議
     * @param {Object} validationResult - 驗證結果
     * @param {Object} summary - 模型摘要
     * @returns {Array} 修正建議列表
     */
    generateCorrections(validationResult, summary) {
        const corrections = [];

        if (!validationResult.isValid) {
            corrections.push('建議回退到基於規則的解釋，因為 LLM 輸出包含錯誤');
        }

        if (validationResult.confidence < 0.8) {
            corrections.push('建議人工檢查 LLM 輸出的準確性');
        }

        // 基於具體錯誤生成建議
        for (const error of validationResult.errors) {
            if (error.includes('格式')) {
                corrections.push(`請確認模型格式為 ${summary.format}`);
            }
            if (error.includes('形狀')) {
                corrections.push('請檢查輸入輸出形狀是否正確');
            }
        }

        return corrections;
    }

    /**
     * 計算整體信心度分數
     * @param {Object} validationResult - 驗證結果
     * @returns {number} 信心度分數 (0-1)
     */
    calculateConfidenceScore(validationResult) {
        let score = validationResult.confidence;

        // 根據錯誤數量調整分數
        score -= validationResult.errors.length * 0.2;
        score -= validationResult.warnings.length * 0.05;

        return Math.max(0, Math.min(1, score));
    }

    /**
     * 驗證 provenance 和 confidence 的合理性
     * @param {Object} summary - 模型摘要
     * @param {Object} validationResult - 驗證結果對象
     */
    _validateProvenance(summary, validationResult) {
        // 檢查輸入的 provenance 和 confidence
        if (summary.inputs) {
            for (const input of summary.inputs) {
                this._checkFieldProvenance(
                    'input',
                    input.name,
                    input.provenance,
                    input.confidence,
                    validationResult
                );
            }
        }

        // 檢查輸出的 provenance 和 confidence
        if (summary.outputs) {
            for (const output of summary.outputs) {
                this._checkFieldProvenance(
                    'output',
                    output.name,
                    output.provenance,
                    output.confidence,
                    validationResult
                );
            }
        }

        // 檢查任務推斷
        if (summary.taskGuess && typeof summary.taskGuess === 'object') {
            this._checkFieldProvenance(
                'task',
                'taskGuess',
                summary.taskGuess.provenance,
                summary.taskGuess.confidence,
                validationResult
            );
        }

        // 檢查量化資訊
        if (summary.quantization && summary.quantization.provenance) {
            this._checkFieldProvenance(
                'quantization',
                'quantization',
                summary.quantization.provenance,
                summary.quantization.confidence,
                validationResult
            );
        }
    }

    /**
     * 檢查單一欄位的 provenance
     */
    _checkFieldProvenance(fieldType, fieldName, provenance, confidence, validationResult) {
        // 檢查 provenance 值是否有效
        const validProvenances = ['model', 'inferred', 'heuristic', 'graph_scan'];
        if (!validProvenances.includes(provenance)) {
            validationResult.provenanceIssues.push({
                field: `${fieldType}.${fieldName}`,
                issue: 'invalid_provenance',
                message: `無效的 provenance 值: ${provenance}`
            });
        }

        // 檢查 confidence 值是否在合理範圍
        if (typeof confidence !== 'number' || confidence < 0 || confidence > 1) {
            validationResult.provenanceIssues.push({
                field: `${fieldType}.${fieldName}`,
                issue: 'invalid_confidence',
                message: `confidence 值應該在 0-1 之間: ${confidence}`
            });
        }

        // 檢查 provenance 和 confidence 的一致性
        if (provenance === 'model' && confidence !== 1.0) {
            validationResult.warnings.push(
                `${fieldType}.${fieldName}: 來自模型的資料 confidence 應為 1.0，實際為 ${confidence}`
            );
        }

        if (provenance === 'inferred' && confidence > 0.9) {
            validationResult.warnings.push(
                `${fieldType}.${fieldName}: 推斷資料的 confidence 過高 (${confidence})，可能不準確`
            );
        }

        if (provenance === 'heuristic' && confidence > 0.8) {
            validationResult.warnings.push(
                `${fieldType}.${fieldName}: 啟發式推斷的 confidence 過高 (${confidence})`
            );
        }
    }

    /**
     * 建議改用規則版本的條件檢查
     * @param {Object} validationResult - 驗證結果
     * @returns {boolean} 是否建議回退到規則版本
     */
    shouldFallbackToRules(validationResult) {
        // 如果有嚴重錯誤，建議回退
        if (validationResult.errors.length > 0) {
            return true;
        }

        // 如果信心度過低，建議回退
        if (validationResult.confidence < 0.6) {
            return true;
        }

        // 如果有太多 provenance 問題，建議回退
        if (validationResult.provenanceIssues && validationResult.provenanceIssues.length > 3) {
            return true;
        }

        return false;
    }

    /**
     * 生成回退建議訊息
     * @param {Object} validationResult - 驗證結果
     * @returns {string} 回退建議訊息
     */
    getFallbackMessage(validationResult) {
        const reasons = [];

        if (validationResult.errors.length > 0) {
            reasons.push(`發現 ${validationResult.errors.length} 個錯誤`);
        }

        if (validationResult.confidence < 0.6) {
            reasons.push(`信心度過低 (${Math.round(validationResult.confidence * 100)}%)`);
        }

        if (validationResult.provenanceIssues && validationResult.provenanceIssues.length > 3) {
            reasons.push(`資料來源問題過多`);
        }

        return `建議回退到規則版本: ${reasons.join(', ')}`;
    }
}

/**
 * UI 渲染器 - 處理徽章顯示和模型小白解碼器的 UI 渲染
 */

export class ExplainUIRenderer {
    constructor() {
        this.provenanceLabels = {
            'model': { text: '來自模型', color: 'green' },
            'inferred': { text: '推斷', color: 'yellow' },
            'heuristic': { text: '推斷', color: 'yellow' },
            'graph_scan': { text: '圖掃描', color: 'blue' }
        };
    }

    /**
     * 渲染欄位值帶徽章
     */
    renderFieldWithBadge(fieldValue, provenance, confidence, container) {
        const wrapper = document.createElement('div');
        wrapper.className = 'field-with-badge';

        // 主內容
        const content = document.createElement('div');
        content.className = 'field-content';

        if (typeof fieldValue === 'string') {
            content.textContent = fieldValue;
        } else if (Array.isArray(fieldValue)) {
            content.textContent = fieldValue.join(', ');
        } else if (typeof fieldValue === 'object') {
            content.textContent = JSON.stringify(fieldValue, null, 2);
        } else {
            content.textContent = String(fieldValue);
        }

        // 徽章
        const badge = this.createProvenianceBadge(provenance, confidence);

        wrapper.appendChild(content);
        wrapper.appendChild(badge);

        if (container) {
            container.appendChild(wrapper);
        }

        return wrapper;
    }

    /**
     * 創建來源徽章
     */
    createProvenianceBadge(provenance, confidence) {
        const badge = document.createElement('span');
        const config = this.provenanceLabels[provenance] || this.provenanceLabels.inferred;

        badge.className = `provenance-badge provenance-${config.color}`;

        let text = config.text;
        if (provenance === 'inferred' || provenance === 'heuristic') {
            const percentage = Math.round((confidence || 0.5) * 100);
            text += ` ${percentage}%`;
        }

        badge.textContent = text;
        badge.title = this.getProvenanceTooltip(provenance, confidence);

        return badge;
    }

    /**
     * 取得來源提示文字
     */
    getProvenanceTooltip(provenance, confidence) {
        const percentage = Math.round((confidence || 0.5) * 100);

        switch (provenance) {
            case 'model':
                return '此資訊直接來自模型定義，準確度最高';
            case 'inferred':
                return `根據模型結構推斷而來，信心度：${percentage}%`;
            case 'heuristic':
                return `基於常見模式推斷，信心度：${percentage}%`;
            case 'graph_scan':
                return `透過圖結構掃描獲得，信心度：${percentage}%`;
            default:
                return '資料來源不明';
        }
    }

    /**
     * 渲染完整的 Explain 面板
     */
    renderExplainPanel(analysisResult, container) {
        container.innerHTML = '';
        container.className = 'explain-panel';
        // 標題與工具列
        const header = this.createPanelHeader(analysisResult);
        container.appendChild(header);

        // 內容區域：建立 tab 容器（預設顯示 LLM 回應）
        const tabContainer = document.createElement('div');
        tabContainer.className = 'explain-tabs';

        const tabsHeader = document.createElement('div');
        tabsHeader.className = 'explain-tabs-header';

        const llmTabBtn = document.createElement('button');
        llmTabBtn.className = 'explain-tab-btn active';
        llmTabBtn.textContent = 'LLM 回應';

        const rawTabBtn = document.createElement('button');
        rawTabBtn.className = 'explain-tab-btn';
        rawTabBtn.textContent = '原始摘要與欄位';

        tabsHeader.appendChild(llmTabBtn);
        tabsHeader.appendChild(rawTabBtn);
        tabContainer.appendChild(tabsHeader);

        const tabsContent = document.createElement('div');
        tabsContent.className = 'explain-tabs-content';

        // LLM 面板 - 顯示原汁原味的完整 LLM 回應（保留 prompt 可收合）
        const llmPanel = document.createElement('div');
        llmPanel.className = 'explain-tab-panel llm-panel';
        // 如果有 explanation 物件，嘗試顯示 prompt（收合）與完整的原始回應
        if (analysisResult.explanation && Object.keys(analysisResult.explanation).length > 0) {
            // 不顯示 Prompt，僅顯示 LLM 的原始回應

            // 顯示完整的 LLM 原始回應，不拆欄位
            const rawText = (analysisResult.explanation._llmRaw) || analysisResult._llmRaw || (analysisResult.explanation && analysisResult.explanation.rawText) || null;
            const rSection = document.createElement('div');
            rSection.className = 'explain-section';
            const rTitle = document.createElement('h3');
            rTitle.textContent = 'LLM 原始回應（完整）';
            rSection.appendChild(rTitle);
            const rContent = document.createElement('div');
            rContent.className = 'explain-section-content';
            const rPre = document.createElement('pre');
            rPre.className = 'llm-raw-pre';
            rPre.textContent = rawText || 'LLM 未提供回應。';
            rContent.appendChild(rPre);
            rSection.appendChild(rContent);
            llmPanel.appendChild(rSection);
        } else {
            const empty = document.createElement('div');
            empty.className = 'explain-section-content';
            empty.textContent = '尚無 LLM 回應可顯示。';
            llmPanel.appendChild(empty);
        }

        // 原始摘要面板（把原有內容放到這裡）
        const rawPanel = document.createElement('div');
        rawPanel.className = 'explain-tab-panel raw-panel';

        // 把原本的 sections 放入 rawPanel
        const overview = this.renderOverview(analysisResult.summary);
        rawPanel.appendChild(overview);
        const inputs = this.renderInputs(analysisResult.summary.inputs);
        rawPanel.appendChild(inputs);
        const outputs = this.renderOutputs(analysisResult.summary.outputs);
        rawPanel.appendChild(outputs);
        const task = this.renderTaskType(analysisResult.summary.taskGuess);
        rawPanel.appendChild(task);
        const quantization = this.renderQuantization(analysisResult.summary.quantization);
        rawPanel.appendChild(quantization);
        if (analysisResult.explanation) {
            const usage = this.renderUsageGuide(analysisResult.explanation);
            rawPanel.appendChild(usage);
        }

        // Raw summary collapse section
        const rawSummarySection = this.renderRawSummary(analysisResult);
        rawPanel.appendChild(rawSummarySection);

        tabsContent.appendChild(llmPanel);
        tabsContent.appendChild(rawPanel);
        tabContainer.appendChild(tabsContent);

        // 切換邏輯
        llmTabBtn.addEventListener('click', () => {
            llmTabBtn.classList.add('active');
            rawTabBtn.classList.remove('active');
            llmPanel.style.display = 'block';
            rawPanel.style.display = 'none';
        });
        rawTabBtn.addEventListener('click', () => {
            rawTabBtn.classList.add('active');
            llmTabBtn.classList.remove('active');
            rawPanel.style.display = 'block';
            llmPanel.style.display = 'none';
        });

        // 預設顯示 LLM 面板，隱藏 rawPanel
        llmPanel.style.display = 'block';
        rawPanel.style.display = 'none';

        container.appendChild(tabContainer);

        // 加入樣式
        this.addStyles();
    }

    /**
     * 創建面板標題
     */
    createPanelHeader(analysisResult) {
        const header = document.createElement('div');
        header.className = 'explain-header';

        const title = document.createElement('h2');
        title.textContent = '模型小白解碼器';
        header.appendChild(title);

        // 工具列
        const toolbar = document.createElement('div');
        toolbar.className = 'explain-toolbar';

        // 重新掃描按鈕
        const rescanBtn = document.createElement('button');
        rescanBtn.className = 'explain-btn rescan-btn';
        rescanBtn.textContent = '重新掃描與校驗';
        rescanBtn.title = '重新分析模型並執行一致性檢查';
        rescanBtn.addEventListener('click', () => {
            this.handleRescan();
        });
        toolbar.appendChild(rescanBtn);

        // 狀態指示
        const status = document.createElement('div');
        status.className = 'explain-status';

        if (analysisResult.validationResult) {
            const validation = analysisResult.validationResult;
            status.className += validation.isValid ? ' status-valid' : ' status-invalid';
            status.textContent = validation.isValid ? '✓ 已驗證' : '✗ 需檢查';
            status.title = validation.message || '';
        } else {
            status.className += ' status-unknown';
            status.textContent = '○ 未驗證';
        }
        toolbar.appendChild(status);

        // Raw summary toggle 按鈕
        const rawToggleBtn = document.createElement('button');
        rawToggleBtn.className = 'explain-btn raw-toggle-btn';
        rawToggleBtn.textContent = 'Raw Summary';
        rawToggleBtn.title = '顯示/隱藏模型原始摘要 (JSON)';
        rawToggleBtn.addEventListener('click', () => {
            document.dispatchEvent(new CustomEvent('explain-toggle-raw-summary'));
        });
        toolbar.appendChild(rawToggleBtn);

        header.appendChild(toolbar);
        return header;
    }

    /**
     * 渲染原始 summary 區塊（收合）
     */
    renderRawSummary(analysisResult) {
        const section = document.createElement('div');
        section.className = 'explain-section raw-summary-section';
        section.style.display = 'none';

        const title = document.createElement('h3');
        title.textContent = 'Raw Summary (JSON)';
        section.appendChild(title);

        const content = document.createElement('div');
        content.className = 'explain-section-content raw-summary-content';

        const pre = document.createElement('pre');
        pre.className = 'raw-summary-pre';

        // 優先從 globalThis 讀取 (DevTools 可用)，否則使用 analysisResult.summary
        let summary = null;
        try {
            summary = (typeof globalThis !== 'undefined' && globalThis.__MODEL_SUMMARY__) ? globalThis.__MODEL_SUMMARY__ : analysisResult.summary;
        } catch {
            summary = analysisResult.summary;
        }

        pre.textContent = JSON.stringify(summary, null, 2);
        content.appendChild(pre);
        section.appendChild(content);

        // 監聽 toggle 事件
        document.addEventListener('explain-toggle-raw-summary', () => {
            section.style.display = section.style.display === 'none' ? 'block' : 'none';
        });

        return section;
    }

    /**
     * 渲染模型概述
     */
    renderOverview(summary) {
        const section = document.createElement('div');
        section.className = 'explain-section';

        const title = document.createElement('h3');
        title.textContent = '模型概述';
        section.appendChild(title);

        const content = document.createElement('div');
        content.className = 'explain-section-content';

        // 模型名稱
        const nameField = this.createField('模型名稱', summary.modelName, 'model', 1.0);
        content.appendChild(nameField);

        // 格式
        const formatField = this.createField('格式', summary.format.toUpperCase(), 'model', 1.0);
        content.appendChild(formatField);

        // 算子統計
        const opsInfo = `總計 ${summary.operators.total} 個算子`;
        const opsField = this.createField('算子', opsInfo, 'graph_scan', 0.95);
        content.appendChild(opsField);

        section.appendChild(content);
        return section;
    }

    /**
     * 渲染輸入說明
     */
    renderInputs(inputs) {
        const section = document.createElement('div');
        section.className = 'explain-section';

        const title = document.createElement('h3');
        title.textContent = '輸入需求';
        section.appendChild(title);

        const content = document.createElement('div');
        content.className = 'explain-section-content';

        for (const input of inputs) {
            const inputDiv = document.createElement('div');
            inputDiv.className = 'input-item';

            // 輸入名稱
            const nameField = this.createField('名稱', input.name, 'model', 1.0);
            inputDiv.appendChild(nameField);

            // 形狀
            const shapeText = Array.isArray(input.shape) ? `[${input.shape.join(', ')}]` : String(input.shape);
            const shapeField = this.createField('形狀', shapeText, 'model', 1.0);
            inputDiv.appendChild(shapeField);

            // 資料類型
            const dtypeField = this.createField('資料類型', input.dtype, 'model', 1.0);
            inputDiv.appendChild(dtypeField);

            // 領域（可能是推斷的）
            const domainField = this.createField('領域', input.domain, input.provenance, input.confidence);
            inputDiv.appendChild(domainField);

            content.appendChild(inputDiv);
        }

        section.appendChild(content);
        return section;
    }

    /**
     * 渲染輸出說明
     */
    renderOutputs(outputs) {
        const section = document.createElement('div');
        section.className = 'explain-section';

        const title = document.createElement('h3');
        title.textContent = '輸出說明';
        section.appendChild(title);

        const content = document.createElement('div');
        content.className = 'explain-section-content';

        for (const output of outputs) {
            const outputDiv = document.createElement('div');
            outputDiv.className = 'output-item';

            // 輸出名稱
            const nameField = this.createField('名稱', output.name, 'model', 1.0);
            outputDiv.appendChild(nameField);

            // 形狀
            const shapeText = Array.isArray(output.shape) ? `[${output.shape.join(', ')}]` : String(output.shape);
            const shapeField = this.createField('形狀', shapeText, 'model', 1.0);
            outputDiv.appendChild(shapeField);

            // 語意（可能是推斷的）
            const semanticsField = this.createField('語意', output.semantics, output.provenance, output.confidence);
            outputDiv.appendChild(semanticsField);

            content.appendChild(outputDiv);
        }

        section.appendChild(content);
        return section;
    }

    /**
     * 渲染任務類型
     */
    renderTaskType(taskGuess) {
        const section = document.createElement('div');
        section.className = 'explain-section';

        const title = document.createElement('h3');
        title.textContent = '任務類型';
        section.appendChild(title);

        const content = document.createElement('div');
        content.className = 'explain-section-content';

        let confidence, provenance, taskValue;
        if (typeof taskGuess === 'object') {
            taskValue = taskGuess.value;
            provenance = taskGuess.provenance;
            confidence = taskGuess.confidence;
        } else {
            taskValue = taskGuess;
            provenance = 'heuristic';
            confidence = 0.5;
        }

        const taskField = this.createField('推斷任務', taskValue, provenance, confidence);
        content.appendChild(taskField);

        section.appendChild(content);
        return section;
    }

    /**
     * 渲染量化資訊
     */
    renderQuantization(quantization) {
        const section = document.createElement('div');
        section.className = 'explain-section';

        const title = document.createElement('h3');
        title.textContent = '量化資訊';
        section.appendChild(title);

        const content = document.createElement('div');
        content.className = 'explain-section-content';

        let confidence, isQuantized, precision, provenance;
        if (typeof quantization === 'object' && quantization.provenance) {
            isQuantized = quantization.isQuantized;
            precision = quantization.precision;
            provenance = quantization.provenance;
            confidence = quantization.confidence;
        } else {
            isQuantized = quantization.isQuantized || false;
            precision = quantization.precision || 'fp32';
            provenance = 'graph_scan';
            confidence = 0.9;
        }

        const quantField = this.createField('量化狀態', isQuantized ? '已量化' : '未量化', provenance, confidence);
        content.appendChild(quantField);

        const precisionField = this.createField('精度', precision, provenance, confidence);
        content.appendChild(precisionField);

        if (quantization.observed && quantization.observed.length > 0) {
            const observedField = this.createField('偵測到算子', quantization.observed.join(', '), provenance, confidence);
            content.appendChild(observedField);
        }

        section.appendChild(content);
        return section;
    }

    /**
     * 渲染使用指南
     */
    renderUsageGuide(explanation) {
        const section = document.createElement('div');
        section.className = 'explain-section';

        const title = document.createElement('h3');
        title.textContent = '使用指南';
        section.appendChild(title);

        const content = document.createElement('div');
        content.className = 'explain-section-content';

        if (explanation.purpose) {
            const purposeField = this.createField('用途', explanation.purpose, 'inferred', 0.7);
            content.appendChild(purposeField);
        }

        if (explanation.applications && explanation.applications.length > 0) {
            const appsField = this.createField('應用場景', explanation.applications.join('; '), 'inferred', 0.6);
            content.appendChild(appsField);
        }

        section.appendChild(content);
        return section;
    }

    /**
     * 創建欄位
     */
    createField(label, value, provenance, confidence) {
        const field = document.createElement('div');
        field.className = 'explain-field';

        const labelEl = document.createElement('div');
        labelEl.className = 'explain-field-label';
        labelEl.textContent = label;
        field.appendChild(labelEl);

        const valueContainer = document.createElement('div');
        valueContainer.className = 'explain-field-value';

        this.renderFieldWithBadge(value, provenance, confidence, valueContainer);
        field.appendChild(valueContainer);

        return field;
    }

    /**
     * 處理重新掃描
     */
    handleRescan() {
        // 觸發重新掃描事件
        const event = new CustomEvent('explain-rescan', {
            detail: { timestamp: Date.now() }
        });
        document.dispatchEvent(event);
    }

    /**
     * 加入樣式
     */
    addStyles() {
        if (document.getElementById('explain-ui-styles')) {
            return;
        }

